'use strict';
const app=document.querySelector('#app');
const practiceManualQuery=new URLSearchParams(location.search).get('flow')==='manual';
function practiceRounds(legacyTotal){let manual=practiceManualQuery;try{manual=manual||localStorage.getItem('spotmatch-answer-pace')==='manual';}catch{}return manual?legacyTotal:1;}

const colors=['#d89565','#72988a','#d7b653','#9e90b2'];
const courses=[
 ['Find my twin','Match two identical objects.','Same picture','Choose the picture that is exactly the same.','#e9efdf'],
 ['Shape spotter','Look closely at the outline.','Shape','Match the shape. Colors stay the same.','#f6ead8'],
 ['Color collector','Notice a change in color.','Color','Match the color. Shapes stay the same.','#e9e5f0'],
 ['Little & large','Compare the size of objects.','Size','Match the size. Everything else stays the same.','#f2e5dc'],
 ['Which way?','Notice which way a shape faces.','Direction','Match the direction of the leaf.','#e3ede7'],
 ['Spot the dots','Look at details inside a shape.','Details','Match the arrangement of dots. No counting needed.','#f4edd5'],
 ['Stripe studio','Compare simple surface patterns.','Pattern','Match the pattern inside the shape.','#ece7ef'],
 ['The missing piece','Notice a detail that is missing.','Parts','Match all the parts of the flower.','#e9edda'],
 ['Look at both','Compare two objects together.','Two features','Match both objects, in the same order.','#e4ecee'],
 ['Discovery garden','Try familiar skills in new combinations.','Fresh examples','Match every detail, using new combinations.','#f3e3d9'],
 ['Shadow friends','Recognize a shape without its colors.','Silhouettes','Find the object with the same outline as the shadow.','#e5e9e0'],
 ['Outline explorer','Connect an outline with a filled picture.','Outlines','Find the picture that fits the outline.','#f5ead7'],
 ['Mirror meadow','Compare a shape with its reflection.','Reflections','Match the way the leaf faces. Look closely at its tip.','#e2eee5'],
 ['Dot positions','Same number of dots, different places.','Positions','Match where the dots sit, not just how many there are.','#eae5f0'],
 ['Space between','Notice the gap between two objects.','Spacing','Find the pair with the same space between the leaves.','#e4ecef'],
 ['Garden search','Find a match among more pictures.','Visual search','Find the exact match among the garden pictures.','#eef0dc'],
 ['Peekaboo picture','Use visible clues to recognize the whole.','Partial pictures','Part is covered. Find the whole picture with the same details.','#f4e6dd'],
 ['Shape stays','Recognize a shape when color and size change.','Shape constancy','Match the shape. Its color and size can change.','#e2eceb'],
 ['Window watch','Notice where a small opening appears.','Fine details','Find the tile with its window in the same position.','#f2ead7'],
 ['Three together','Compare every part of a small group.','Whole arrangements','Match all three objects in the same positions.','#e9e5ed'],
 ['Shape sorter','Send each object to its shape home.','Sorting by shape','Look at the object. Tap the home with the same shape.','#e5eedf'],
 ['Pair-up garden','Connect matching pictures, all face up.','Comparing pairs','Tap one picture, then tap its matching partner.','#f4e6dc'],
 ['Make my mushroom','Change two details to copy a model.','Comparing features','Change the color and dots until your mushroom matches the model.','#e9e4ef'],
 ['Turn to match','Rotate a leaf into the matching direction.','Orientation','Use the turn buttons. Make your leaf face the same way as the model.','#e3ece9'],
 ['What changed?','Find one changed detail in a picture row.','Comparing scenes','Compare the two rows. Tap the picture that changed in the lower row.','#f2ecd7']
];
let saved={};try{saved=JSON.parse(localStorage.getItem('spotmatch-v1')||'{}')||{}}catch{};
let game=0,round=0,correct=0,hints=0,hadError=false,usedHint=false,answered=false,current=null,sessionSeed=0;
const persist=()=>{try{localStorage.setItem('spotmatch-v1',JSON.stringify(saved))}catch{}};
const shuffle=a=>{for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function baseArt(o={}){let {shape=0,color=0,size=1,dir=0,dots=0,pattern=0,missing=0,second=null}=o;let fill=colors[color];let inner='';
 if(shape===0){for(let i=0;i<6;i++){if(missing===1&&i===0)continue;inner+=`<ellipse cx="60" cy="31" rx="12" ry="19" fill="${fill}" transform="rotate(${i*60} 60 60)"/>`}inner+='<circle cx="60" cy="60" r="16" fill="#f5d875" stroke="#596e4f" stroke-width="2"/>'}
 if(shape===1)inner=`<path d="M26 85Q12 23 92 24Q99 85 26 85Z" fill="${fill}"/><path d="M26 85L80 35M46 64L40 40M62 48L81 51" stroke="#38564a" stroke-width="3" fill="none"/>`;
 if(shape===2)inner=`<path d="M48 59L45 99Q60 108 75 99L71 59" fill="#e9d8b3" stroke="#667653" stroke-width="2"/><path d="M14 62Q18 12 60 12Q104 12 107 62Z" fill="${fill}" stroke="#667653" stroke-width="2"/>`;
 if(shape===3)inner=`<path d="M20 60Q58 9 94 60Q58 111 20 60ZM20 60L6 39V81Z" fill="${fill}"/><circle cx="77" cy="53" r="3" fill="#294d40"/>`;
 if(pattern===1)inner+='<path d="M38 35L38 80M54 28L54 89M70 30L70 84M86 38L86 72" stroke="#fff9" stroke-width="5"/>';
 if(pattern===2)inner+='<path d="M28 46H90M27 60H94M31 74H85" stroke="#fff9" stroke-width="5"/>';
 if(dots){const layouts={1:[[60,56]],2:[[44,56],[76,56]],3:[[44,44],[76,44],[60,74]],4:[[44,44],[76,44],[44,74],[76,74]]};for(const [x,y] of layouts[dots])inner+=`<circle cx="${x}" cy="${y}" r="6" fill="#fffdf2" stroke="#536d52" stroke-width="1.5"/>`}
 let group=`<g transform="translate(60 60) scale(${size===0?.65:1}) rotate(${dir*90}) translate(-60 -60)">${inner}</g>`;
 if(second!==null){const other=art({...o,shape:second,second:null});return `<svg viewBox="0 0 240 120" aria-hidden="true"><svg x="0" width="120" viewBox="0 0 120 120">${group}</svg><svg x="120" width="120" viewBox="0 0 120 120">${other.match(/<svg[^>]*>([\s\S]*)<\/svg>/)[1]}</svg></svg>`}
 return `<svg viewBox="0 0 120 120" aria-hidden="true">${group}</svg>`;
}
function svgBody(svg){return svg.replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}
function art(o={}){
 if(!o.kind)return baseArt(o);
 const outer=body=>`<svg viewBox="0 0 120 120" aria-hidden="true">${body}</svg>`;
 if(o.kind==='shadow')return baseArt({...o,kind:null}).replace(/fill="[^"]*"/g,'fill="#30483e"').replace(/stroke="[^"]*"/g,'stroke="#30483e"');
 if(o.kind==='outline')return outer(`<g stroke="#30483e" stroke-width="3">${svgBody(baseArt({...o,kind:null})).replace(/fill="[^"]*"/g,'fill="none"').replace(/ stroke="[^"]*"/g,'').replace(/ stroke-width="[^"]*"/g,'')}</g>`);
 if(o.kind==='mirror')return outer(`<g transform="${o.flip?'translate(120 0) scale(-1 1)':'translate(0 0)'}">${svgBody(baseArt({...o,kind:null}))}</g>`);
 if(o.kind==='positions'){
 const sets=[[[37,37],[83,83]],[[37,83],[83,37]],[[37,60],[83,60]],[[60,37],[60,83]]];
 return outer(`<rect x="14" y="14" width="92" height="92" rx="23" fill="${colors[o.color]}"/>${sets[o.layout].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="10" fill="#fffdf3" stroke="#30483e" stroke-width="2"/>`).join('')}`);
 }
 if(o.kind==='spacing'){
 const x=[33,46,58][o.gap];return outer([60-x/2,60+x/2].map(cx=>`<g transform="translate(${cx-18} 30) scale(.3 .5)">${svgBody(baseArt({shape:1,color:o.color}))}</g>`).join(''));
 }
 if(o.kind==='covered')return outer(svgBody(baseArt({...o,kind:null}))+`<rect x="${o.side?60:0}" y="0" width="60" height="120" rx="0" fill="#e5e8df"/><path d="M60 5V115" stroke="#a0af98" stroke-width="2" stroke-dasharray="5 5"/>`);
 if(o.kind==='window'){
 const positions=[[37,37],[83,37],[37,83],[83,83]];let [x,y]=positions[o.window];return outer(`<rect x="15" y="15" width="90" height="90" rx="18" fill="${colors[o.color]}"/><rect x="${x-10}" y="${y-10}" width="20" height="20" rx="4" fill="#fffdf8" stroke="#30483e" stroke-width="2"/>`);
 }
 if(o.kind==='trio')return outer(o.items.map((shape,i)=>`<g transform="translate(${i*39+1} 35) scale(.32 .42)">${svgBody(baseArt({shape,color:1}))}</g>`).join(''));
 return baseArt(o);
}
function lessonData(g,r){let target={shape:(r+sessionSeed)%4,color:(r+sessionSeed)%4,size:1,dir:0,dots:0,pattern:0,missing:0,second:null};let choices=[];
 if(g===0){choices=[target,{...target,shape:(target.shape+1)%4,color:(target.color+1)%4}]}
 if(g===1){target.color=1;choices=[target,{...target,shape:(target.shape+1)%4},{...target,shape:(target.shape+2)%4}]}
 if(g===2){target.shape=2;choices=[target,{...target,color:(target.color+1)%4},{...target,color:(target.color+2)%4}]}
 if(g===3){target.size=r%2;choices=[target,{...target,size:1-target.size}]}
 if(g===4){target.shape=1;target.dir=r%4;choices=[target,{...target,dir:(target.dir+1)%4},{...target,dir:(target.dir+2)%4}]}
 if(g===5){target.shape=2;target.dots=1+r%4;choices=[target,{...target,dots:1+target.dots%4},{...target,dots:1+(target.dots+1)%4}]}
 if(g===6){target.shape=3;target.pattern=r%3;choices=[target,{...target,pattern:(target.pattern+1)%3},{...target,pattern:(target.pattern+2)%3}]}
 if(g===7){target.shape=0;target.missing=r%2;choices=[target,{...target,missing:1-target.missing}]}
 if(g===8){target.second=(target.shape+1)%4;choices=[target,{...target,shape:target.second,second:target.shape},{...target,second:(target.second+1)%4}]}
 if(g===9){target.shape=2;target.dots=1+r%4;target.size=r%2;choices=[target,{...target,color:(target.color+1)%4},{...target,dots:1+target.dots%4},{...target,size:1-target.size}]}
 if(g===10){target.shape=(r+sessionSeed)%4;target.color=1;target.kind='shadow';choices=[{...target,kind:null},{...target,kind:null,shape:(target.shape+1)%4},{...target,kind:null,shape:(target.shape+2)%4}]}
 if(g===11){target.kind='outline';target.color=1;choices=[{...target,kind:null},{...target,kind:null,shape:(target.shape+1)%4},{...target,kind:null,shape:(target.shape+2)%4}]}
 if(g===12){target.shape=1;target.kind='mirror';target.flip=r%2;choices=[target,{...target,flip:1-target.flip}]}
 if(g===13){target.kind='positions';target.layout=(r+sessionSeed)%4;choices=[target,{...target,layout:(target.layout+1)%4},{...target,layout:(target.layout+2)%4}]}
 if(g===14){target.kind='spacing';target.gap=r%3;choices=[target,{...target,gap:(target.gap+1)%3},{...target,gap:(target.gap+2)%3}]}
 if(g===15){target.shape=(r+sessionSeed)%4;target.color=r%4;choices=[target,{...target,color:(target.color+1)%4},{...target,shape:(target.shape+1)%4},{...target,shape:(target.shape+2)%4},{...target,color:(target.color+2)%4},{...target,shape:(target.shape+3)%4}]}
 if(g===16){target.kind='covered';target.shape=3;target.pattern=r%3;target.side=r%2;choices=[{...target,kind:null},{...target,kind:null,pattern:(target.pattern+1)%3},{...target,kind:null,pattern:(target.pattern+2)%3}]}
 if(g===17){target.size=1;let match={...target,color:(target.color+1)%4,size:r%2};choices=[match,{...target,shape:(target.shape+1)%4,color:(target.color+2)%4,size:1-r%2},{...target,shape:(target.shape+2)%4,color:(target.color+3)%4,size:r%2}]}
 if(g===18){target.kind='window';target.window=(r+sessionSeed)%4;choices=[target,{...target,window:(target.window+1)%4},{...target,window:(target.window+2)%4},{...target,window:(target.window+3)%4}]}
 if(g===19){target.kind='trio';target.items=[r%4,(r+1)%4,(r+2)%4];choices=[target,{...target,items:[target.items[1],target.items[0],target.items[2]]},{...target,items:[target.items[0],target.items[2],target.items[1]]}]}
 if(g>=20){target.shape=g===22?2:g===23?1:g===24?3:g%4;target.dots=g===22?3:0;choices=[target]}
 return{target,choices:shuffle(choices.map((o,i)=>({o,match:i===0})))}}
function home(){let done=Object.keys(saved).filter(k=>saved[k]?.complete).length;app.innerHTML=`<section class="hero"><div><span class="eyebrow pill">A LITTLE COURSE FOR CURIOUS MINDS</span><h1>Little discoveries.<br><em>Growing skills.</em></h1><p>A gentle journey in noticing what’s the same, what’s different, and all the little details in between.</p><div class="hero-actions"><button class="primary" id="start">${done?'Continue exploring':'Let’s explore'} <span aria-hidden="true">→</span></button><span class="micro">${courses.length} games · At your own pace</span></div></div><div class="illustration" aria-hidden="true"><span class="art-star">✧</span><div class="art-card one">${art({shape:0,color:0})}</div><div class="art-card two">${art({shape:0,color:0})}</div><span class="check-art">✓</span><span class="art-caption">A MATCH WORTH NOTICING</span></div></section><section class="intro"><div><b>THE CHALLENGE</b><p>A child may choose by color alone, miss a small detail, or lose a target among other pictures. We practice comparing what matters, with the model kept in view.</p></div><div><b>OUR GOAL · VISUAL DISCRIMINATION</b><p>Learn to compare pictures deliberately: notice shape, color, size, direction, and small details, then select the picture that fits the rule.</p></div></section><section class="skill-explainer" aria-labelledby="skill-title"><div><span class="eyebrow">WHAT WE ARE DEVELOPING</span><h2 id="skill-title">Looking with a purpose.</h2><p>Visual discrimination means noticing how things are alike and different. A child looks at a model, compares the choices, and checks the relevant features before selecting.</p><p>We practice <b>outlines and shapes</b>, <b>small details</b>, <b>direction and position</b>, and <b>more than one feature at once</b>. Later games introduce shadows, partial pictures, and a larger choice set.</p></div><div class="everyday-card"><b>Why it can be useful</b><p>These are opportunities to practice skills used when comparing toys, matching materials, or finding a picture on a choice board. Whether game learning transfers to those activities must be checked with real examples.</p><p class="micro">The model stays visible. No naming, counting, fast responses, or remembering a hidden picture is required.</p></div></section><section class="who-section" aria-labelledby="who-title"><span class="eyebrow">WHO MIGHT FIND IT USEFUL?</span><h2 id="who-title">Choose by the child’s needs.</h2><p>A diagnosis does not tell us whether a child needs these games. Look for a specific matching or comparison difficulty, and begin where the child feels comfortable.</p><div class="support-grid"><article><h3>Autistic children</h3><p>May find targeted practice useful if they match by one detail, such as color, and overlook others. This is not a difficulty every autistic child has.</p></article><article><h3>Developmental delay or intellectual disability</h3><p>May benefit from short, repeated opportunities to compare and match, with a clear example and gradual removal of help. This can include children with Down syndrome when the task fits their needs.</p></article><article><h3>Children with language or speech difficulties</h3><p>Can participate without naming a picture or producing speech. Demonstrate the task first; silence does not automatically make instructions understandable.</p></article><article><h3>Children who use AAC or picture choices</h3><p>May use these games as extra picture-comparison practice. They are not a prerequisite for AAC, and a child’s communication system should remain available throughout.</p></article></div><p class="access-note"><b>Access matters.</b> Children with attention or motor difficulties may need adult support, breaks, or a different input method. Color-only games may not suit children with color-vision differences. Low vision or cerebral visual impairment needs individual advice; busy or partly covered pictures may be unsuitable. These games are not vision therapy or a treatment for dyslexia.</p><button class="secondary" id="moreGuide">Read the grown-up guide ↗</button></section><section id="journey"><div class="section-head"><div><span class="eyebrow">THE LEARNING PATH</span><h2>One small step at a time.</h2><p>Start with game 1. Revisit any game whenever you like.</p></div><div class="progress-label">${done} of ${courses.length} explored<div class="progress-track"><i style="width:${done/courses.length*100}%"></i></div></div></div><div class="path-label"><span>01—10</span> Foundations · one feature at a time</div><div class="grid">${courses.slice(0,10).map((c,i)=>`<button class="course-card ${saved[i]?.complete?'completed':''}" data-game="${i}"><div class="thumb" style="--tint:${c[4]}">${art(lessonData(i,0).target)}${i===0?art({shape:0,color:0}):''}</div><span class="card-num">GAME ${String(i+1).padStart(2,'0')}</span><h3>${c[0]}</h3><p>${c[1]}</p><div class="card-bottom"><span>${saved[i]?.complete?'✓ Practiced':'5 little rounds'}</span><span aria-hidden="true">↗</span></div></button>`).join('')}</div><div class="path-label second-path"><span>11—20</span> Look closer · new ways to compare</div><div class="grid">${courses.slice(10,20).map((c,j)=>{let i=j+10;return `<button class="course-card ${saved[i]?.complete?'completed':''}" data-game="${i}"><div class="thumb" style="--tint:${c[4]}">${art(lessonData(i,0).target)}${i===0?art({shape:0,color:0}):''}</div><span class="card-num">GAME ${String(i+1).padStart(2,'0')}</span><h3>${c[0]}</h3><p>${c[1]}</p><div class="card-bottom"><span>${saved[i]?.complete?'✓ Practiced':'5 little rounds'}</span><span aria-hidden="true">↗</span></div></button>`}).join('')}</div><div class="path-label second-path"><span>21—25</span> Hands-on discoveries · sort, build, and turn</div><div class="grid">${courses.slice(20).map((c,j)=>{let i=j+20;return `<button class="course-card ${saved[i]?.complete?'completed':''}" data-game="${i}"><div class="thumb" style="--tint:${c[4]}">${art(lessonData(i,0).target)}${i===0?art({shape:0,color:0}):''}</div><span class="card-num">GAME ${String(i+1).padStart(2,'0')}</span><h3>${c[0]}</h3><p>${c[1]}</p><div class="card-bottom"><span>${saved[i]?.complete?'✓ Practiced':'5 little rounds'}</span><span aria-hidden="true">↗</span></div></button>`}).join('')}</div><p class="note">Designed for gentle practice. No timers or scores to compete for. Progress stays on this device. <button class="back" id="about">About this course ↗</button></p></section>`;document.querySelector('#start').onclick=()=>intro(courses.findIndex((_,i)=>!saved[i]?.complete)<0?0:courses.findIndex((_,i)=>!saved[i]?.complete));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>intro(+b.dataset.game));document.querySelector('#about').onclick=guide;document.querySelector('#moreGuide').onclick=guide;}
function shell(content,keepScroll=false){app.innerHTML=`<div class="play-top"><button class="back" id="back">← Back to the course</button><span class="micro">GAME ${game+1} OF ${courses.length} · ${courses[game][2]}</span></div><section class="game-wrap">${content}</section>`;document.querySelector('#back').onclick=home;if(!keepScroll)window.scrollTo({top:0,behavior:'instant'})}
function intro(g){if(g>=20){interactiveIntro(g);return}game=g;round=0;correct=0;hints=0;sessionSeed=Math.floor(Math.random()*8);let d=lessonData(g,0);let example=d.choices.find(c=>c.match).o;shell(`<span class="eyebrow">LOOK FIRST, THEN TRY</span><h1>${courses[g][0]}</h1><p>${courses[g][3]}</p><div class="game-stage"><span class="micro">These belong together · Notice the matching feature</span><div class="demo-row"><div class="demo-tile">${art(d.target)}</div><span class="demo-arrow" aria-hidden="true">→</span><div class="demo-tile">${art(example)}<span aria-hidden="true">✓</span></div></div><p>Look at the picture above. Then tap its match below.</p><button class="primary" id="begin">Start playing →</button></div>`);document.querySelector('#begin').onclick=play;}
function play(){if(game>=20){interactivePlay();return}hadError=false;usedHint=false;answered=false;current=lessonData(game,round);shell(`<span class="eyebrow">${courses[game][2].toUpperCase()}</span><h1>${courses[game][0]}</h1><p>${courses[game][3]}</p><div class="game-stage"><div class="target" role="img" aria-label="Picture to match">${art(current.target)}</div><div class="choices ${game===15?'search-choices':''}">${current.choices.map((c,i)=>`<button class="choice" data-choice="${i}" aria-label="Choose picture ${i+1}">${art(c.o)}</button>`).join('')}</div><div class="feedback" role="status" aria-live="polite">Find its match.</div><div class="game-controls"><button class="secondary" id="hint">Show me a clue</button><button class="primary" id="next" hidden>Next →</button></div></div><div class="play-top"><span class="micro">${practiceRounds(5)===1?'One little discovery':`Round ${round+1} of ${practiceRounds(5)}`}</span><div class="round-dots" aria-hidden="true">${Array.from({length:practiceRounds(5)},(_,i)=>`<i class="${i<round?'done':i===round?'current':''}"></i>`).join('')}</div><button class="back" id="model">See example ↗</button></div>`);document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>choose(+b.dataset.choice,b));document.querySelector('#hint').onclick=()=>{if(answered)return;if(!usedHint){hints++;usedHint=true}document.querySelectorAll('.choice').forEach((b,i)=>{if(current.choices[i].match)b.classList.add('hinted')});document.querySelector('.feedback').textContent='Look at the outlined picture. Compare it with the model.'};document.querySelector('#model').onclick=()=>{const d=document.createElement('dialog');d.innerHTML=`<button class="close" aria-label="Close example">×</button><h2>Look for the same details</h2><div class="demo-row"><div class="demo-tile">${art(current.target)}</div><span class="demo-arrow">→</span><div class="demo-tile">${art(current.choices.find(c=>c.match).o)}</div></div><p>${courses[game][3]}</p>`;document.body.append(d);d.querySelector('button').onclick=()=>{d.close();d.remove()};d.showModal();if(!usedHint){hints++;usedHint=true}};document.querySelector('#next').onclick=()=>{round++;round<practiceRounds(5)?play():finish()};}
function choose(i,b){if(answered)return;if(!current.choices[i].match){hadError=true;b.classList.add('wrong');document.querySelector('.feedback').textContent='Look again. Compare it with the picture above.';return}answered=true;if(!hadError&&!usedHint)correct++;b.classList.add('correct');document.querySelector('.feedback').textContent='✓ You found the match!';document.querySelectorAll('.choice').forEach(x=>x.disabled=true);document.querySelector('#hint').hidden=true;document.querySelector('#next').hidden=false;document.querySelector('#next').focus()}
function finish(){saved[game]={complete:true,independent:correct,hints,date:new Date().toISOString()};persist();shell(`<span class="eyebrow">A LITTLE DISCOVERY, WELL DONE</span><div class="success-icon" aria-hidden="true">✳</div><h1>You explored ${courses[game][2].toLowerCase()}!</h1><p>${practiceRounds(5)===1?'One discovery. Repeat if you like, or explore a different activity.':'Five rounds of looking closely. Take a break or try the next discovery.'}</p><div class="completion-stat"><div><b>${practiceRounds(5)}</b><span>rounds practiced</span></div><div><b>${correct}</b><span>rounds without retries or hints</span></div></div><p class="micro">Practice completed · This is not a mastery assessment.</p><div class="game-controls"><button class="secondary" id="again">Play again</button><button class="primary" id="continue">${game<courses.length-1?'Next game →':'Back to the course →'}</button></div>`);document.querySelector('#again').onclick=()=>intro(game);document.querySelector('#continue').onclick=()=>game<courses.length-1?intro(game+1):home()}
function guide(){document.querySelector('#guide').showModal()};document.querySelector('#guideNav').onclick=guide;document.querySelector('#guide .close').onclick=()=>document.querySelector('#guide').close();document.querySelector('#reset').onclick=()=>{if(confirm('Clear course progress saved on this device?')){saved={};persist();document.querySelector('#guide').close();home()}};document.querySelector('#brand').onclick=e=>{e.preventDefault();home()};document.querySelector('#courseNav').onclick=()=>{home();document.querySelector('#journey').scrollIntoView({behavior:'smooth'})};home();
